/**
 * Area icon pilot, generated from packages/icons/sources by
 * packages/icons/scripts/generate.mjs. Do not edit by hand. Construction: docs/specs/icons.md.
 * Each icon is a stroked 16px drawing. The line weight follows --area-weight-icon (1.125px for
 * Geist); pass `weight` in CSS pixels to override it, as the gallery comparison does.
 * Filled variants are derived from each shape's data-filled role; cut-outs use a mask.
 */
import { useId, type SVGProps } from "react";

/** weight: line in CSS px at 16px (overrides --area-weight-icon). size: rendered size in px;
 *  the line then follows the size curve instead of scaling with the drawing. title: the icon's
 *  accessible name, for an icon that means something on its own (an icon beside its own text stays
 *  decorative). mirrored: true flips the drawing, false keeps it; left out, an icon tied to reading
 *  direction mirrors in right-to-left text (rtl.css). docs/specs/icons.md, "Accessible name and right-to-left". */
export type PilotIconProps = Omit<SVGProps<SVGSVGElement>, "stroke"> & { weight?: number; size?: number; title?: string; mirrored?: boolean };
/** Size curve (docs/specs/icons.md, "Sizes"): the line grows with size^0.45, Cursor's
 *  16 → 24px step (1.25 → 1.5px), up to the 24px master; above it with size^0.74, Fluent's slope
 *  between its 24 and 48 masters. In drawing units that is a factor of (size / 16)^-0.55 to 24,
 *  then (24 / 16)^-0.55 × (size / 24)^-0.26. */
export const sizeFactor = (size?: number) => !size ? 1 : size <= 24
  ? Math.pow(size / 16, -0.55)
  : Math.pow(24 / 16, -0.55) * Math.pow(size / 24, -0.26);
export const sw = (weight: number | undefined, size: number | undefined, ratio = 1) => {
  const k = ratio * sizeFactor(size);
  if (weight !== undefined) return weight * k;
  // The token line at 12 is the xs icon slot's (16px at type 16): the 12px factor applies where the slot is 12.
  if (size === 12) return `calc(var(--area-weight-icon) * ${ratio.toFixed(4)} * (1 + ${(sizeFactor12 - 1).toFixed(4)} * var(--_glyph-cut, var(--area-type-icon-xs-cut, 1))))`;
  return k === 1 ? "var(--area-weight-icon)" : `calc(var(--area-weight-icon) * ${k.toFixed(4)})`;
};
const sizeFactor12 = sizeFactor(12);
/** A 12px cut's line in its own units (one unit is a pixel at 12): the size curve's line at 12, 0.8786× the
 *  16px line (docs/specs/icons.md, "12px cuts"). */
export const sw12 = (weight: number | undefined) => weight !== undefined ? weight * 0.8786 : "calc(var(--area-weight-icon) * 0.8786)";
/** Which drawing an icon with a 12px cut shows at size 12 (token line): the cut where the xs icon slot is 12, from a
 *  component's --_glyph-cut or the type axis's --area-type-icon-xs-cut; without Area's styles, the cut. */
export const cutOpacity = (cut: boolean) => cut ? "var(--_glyph-cut, var(--area-type-icon-xs-cut, 1))" : "calc(1 - var(--_glyph-cut, var(--area-type-icon-xs-cut, 1)))";
/** A 10px cut's line in its own units (one unit is a pixel at 10): 0.8094× the 16px line ("10px cuts"). */
export const sw10 = (weight: number | undefined) => weight !== undefined ? weight * 0.8094 : "calc(var(--area-weight-icon) * 0.8094)";
/** An icon with a 10px cut, at size 12 (token line): the 10px cut shows where a mark's slot is 10 (a component's
 *  --_glyph-cut10, 1 in Compact's 14px marks); the other drawings give way to it there. */
export const cut10Opacity = (layer: 16 | 12 | 10, has12: boolean) => {
  const c12 = "var(--_glyph-cut, var(--area-type-icon-xs-cut, 1))", c10 = "var(--_glyph-cut10, 0)";
  if (layer === 10) return c10;
  if (layer === 12) return `calc(${c12} * (1 - ${c10}))`;
  return has12 ? `calc((1 - ${c12}) * (1 - ${c10}))` : `calc(1 - ${c10})`;
};
/** A halo's width: the line and one line of space on each side, so the cut round a part in front is
 *  the line's own weight at every size (owner, 2026-10-06: the overlap cut's fixed 2.25 grew to 1.5×
 *  the line above 24px). */
export const haloWidth = (weight: number | undefined, size: number | undefined) => sw(weight, size, 3);
/** data-shift: a line moved by (dx, dy) × (the 16px weight − the rendered weight). Returns the line's
 *  stroke props, as slashGap does: a numeric weight shifts by the SVG transform attribute in user
 *  units, the token weight by a CSS transform computed from the token. */
export const lineShift = (weight: number | undefined, size: number | undefined, dx: number, dy: number) => {
  const w = sw(weight, size), d = 1 - sizeFactor(size);
  if (!d) return { style: { strokeWidth: w } };
  if (weight !== undefined) return { style: { strokeWidth: w }, transform: `translate(${(weight * d * dx).toFixed(4)} ${(weight * d * dy).toFixed(4)})` };
  const t = (k: number) => `calc(var(--area-weight-icon) * ${(d * k).toFixed(4)})`;
  return { style: { strokeWidth: w, transform: `translate(${t(dx)}, ${t(dy)})` } };
};
/** The slash's filled gap: the slash shifted one line weight across it (centre to centre).
 *  Returns the slash's stroke props. A numeric weight is drawing units like the path, so the
 *  shift is the SVG transform attribute in user units; the token weight is a CSS length, so
 *  its shift is a CSS transform computed from the token. */
export const slashGap = (weight: number | undefined, size: number | undefined, side = 1) => {
  const w = sw(weight, size);
  if (typeof w === "number") {
    const t = side * w * Math.SQRT1_2;
    return { style: { strokeWidth: w }, transform: `translate(${t.toFixed(4)} ${(-t).toFixed(4)})` };
  }
  const t = `calc(${w.startsWith("calc") ? w.slice(5, -1) : w} * ${(side * 0.7071).toFixed(4)})`;
  return { style: { strokeWidth: w, transform: `translate(${t}, calc(-1 * ${t}))` } };
};
const base = { viewBox: "0 0 16 16", width: 16, height: 16, fill: "none" } as const;
/** The root svg's props. Decorative (aria-hidden) unless named by title, aria-label or aria-labelledby,
 *  then role="img" (Fluent's and Octicons' pattern). An icon tied to reading direction (rtl) carries
 *  data-area-rtl="mirror" for rtl.css's :dir(rtl) flip, which needs no context and renders the same on the
 *  server; mirrored flips it inline with the scale property, so a transform of the caller's still applies.
 *  Props passed through come last and win. */
export const root = (size: number | undefined, { title, mirrored, style, ...props }: Omit<PilotIconProps, "weight" | "size">, rtl?: boolean, grid?: 12 | 10) => {
  const named = title !== undefined || props["aria-label"] !== undefined || props["aria-labelledby"] !== undefined;
  return {
    ...base, ...(grid ? { viewBox: `0 0 ${grid} ${grid}` } : {}), ...(size ? { width: size, height: size } : {}),
    ...(named ? { role: "img", ...(title !== undefined ? { "aria-label": title } : {}) } : { "aria-hidden": true }),
    focusable: props.tabIndex !== undefined && props.tabIndex >= 0,
    ...(rtl && mirrored === undefined ? { "data-area-rtl": "mirror" } : {}),
    ...(mirrored ? { style: { scale: "-1 1", ...style } } : style ? { style } : {}),
    ...props,
  };
};
const useMaskId = () => "area-icon-" + useId().replace(/[^A-Za-z0-9-]/g, "");

